'use strict';
function paginationHTML(page,pages,kind,total){return pages<=1?'':`<div class="pagination"><span>${(page-1)*25+1}–${Math.min(page*25,total)} of ${total}</span><div><button class="btn secondary" data-${kind}-page="${page-1}" ${page===1?'disabled':''}>← Previous</button><span>Page ${page} / ${pages}</span><button class="btn secondary" data-${kind}-page="${page+1}" ${page===pages?'disabled':''}>Next →</button></div></div>`;}
function sourceQuestionHTML(p){return `<div class="source-question">${p.images.map((src,i)=>`<img src="${src}" alt="${esc(p.title)}${i?', continued':''}. Original question with formulas and diagrams. ${i?'':esc(p.sourceText)}" loading="lazy">`).join('')}</div><div class="source-credit"><a href="${p.sourceUrl}" target="_blank" rel="noopener">Original ${esc(p.source)} ${p.year} · Q${esc(p.question)} ↗</a><span>© University of Waterloo · <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noopener">CC BY-NC 4.0</a></span><small>Excerpted from the original PDF. Topic and difficulty tags added for study.</small></div>`;}
function sourceSolutionHTML(p){return `<p class="meta-text"><a href="${p.solutionUrl}" target="_blank" rel="noopener">Open the official solution PDF ↗</a></p><div class="source-solution">${p.solutionImages.map((src,i)=>`<img src="${src}" alt="Official ${esc(p.source)} ${p.year} solution to question ${esc(p.question)}, section ${i+1}. Use the linked PDF for selectable text." loading="lazy">`).join('')}</div><p class="meta-text">© University of Waterloo · CC BY-NC 4.0 · Cropped excerpts from the official worked solution.</p>`;}
function sourcesPage(){
 const imported=window.SOURCED_PROBLEMS||[];const count=s=>imported.filter(p=>p.source===s).length;
 return `${heading('Good problems deserve good credit.','Official competition sources. Clear provenance for every question.','SOURCES & LICENSE')}<article class="source-guide"><h2>600 sourced problems, alongside the original starter bank</h2><p>The imported bank contains 300 problems assigned to the AMC 12 preparation track and 300 to the AIME preparation track. These are study groupings, not official AMC or AIME questions and not claims of exact difficulty equivalence.</p><ul><li><b>Fermat:</b> ${count('Fermat')} problems from 2000–2025. Questions 11–22 form the AMC 12 practice set; selected final questions support the AIME track.</li><li><b>Euclid:</b> ${count('Euclid')} problems from 1998–2025, questions 6–10. Includes multipart questions and proofs.</li><li><b>Canadian Senior Mathematics Contest:</b> ${count('CSMC')} problems from 2011–2025, excluding 2020: Part A questions 4–6 and Part B questions 1–3.</li></ul><h2>How to use the formats</h2><p>Multiple-choice and integer-response Fermat problems use the official answer keys. For written-response questions, compare your work with the included official solution and record your own assessment. Self-assessed written work appears in your progress, but is excluded from automatic answer accuracy.</p><p>Topic tags are assigned from the question text and may be approximate, especially for multipart problems. Difficulty labels are broad study labels. Use the format filter to choose automatically checked questions or written-response practice.</p><h2>Attribution and reuse</h2><p>Contest questions, diagrams, and official solutions are © University of Waterloo, Centre for Education in Mathematics and Computing (CEMC), and are supplied under <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noopener">Creative Commons Attribution–NonCommercial 4.0 International</a>, following the <a href="https://cemc.uwaterloo.ca/copyright" target="_blank" rel="noopener">CEMC copyright policy</a>. Their materials must remain free to access.</p><p>Each entry links to its original official contest and solution PDF. We cropped excerpts from these PDFs to preserve mathematical notation and diagrams, and added track, topic, and difficulty tags. No AoPS Wiki material was used. The 2005 Fermat question 25 was excluded because the official solution includes a correction to the question.</p><p>Archive: <a href="https://cemc.uwaterloo.ca/resources/past-contests" target="_blank" rel="noopener">CEMC past contests, solutions and results ↗</a></p><p class="meta-text">Summit is independent of CEMC, the University of Waterloo, and MAA. The sourced collection is for noncommercial study.</p></article>`;
}
function selfReviewProblem(correct){
 if(!pv||pv.submitted||!pv.revealed)return;
 const p=allProblems().find(p=>p.id===pv.id);if(p?.format!=='written')return;
 pv.submitted=true;pv.correct=correct;pv.assisted=false;pv.selfReported=true;
 state.attempts.push({id:p.id,correct,assisted:false,selfReported:true,day:dayKey(),time:Date.now()});
 if(!correct)addNote(p.id);else if(state.notes[p.id])state.notes[p.id].reviewed=true;
 if(session&&pv.context==='session')session.results[p.id]={correct,assisted:false,selfReported:true};
 save();updateCount();updateProblem();if(pv.context==='daily')refreshStats();
}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.bankPage){bankPage=Number(d.bankPage);$('#problem-results').innerHTML=problemResults();$('#search-problems').scrollIntoView({block:'start'});}if(d.selfReview)selfReviewProblem(d.selfReview==='solved');});
